 70		if (!isStructuredObject(toolOutput)) return null;
 71		if (Object.hasOwn(toolOutput, "structuredContent")) {
 72			return isStructuredObject(toolOutput.structuredContent)
 73				? (toolOutput.structuredContent as T)
